// Block (composition) — an aggregate rating paired with a five-to-one-star distribution.
// Meter, Rating and Stack own their look and responsive layout behavior.
import { useLocale } from "react-aria-components";
import { Meter } from "../components/Meter";
import { Rating } from "../components/Rating";
import { Stack } from "../layouts/Stack";
import "./RatingSummary.css";

export interface RatingSummaryProps {
  average: number;
  count: number;
  distribution: { stars: number; count: number }[];
  /** The scale under the score, in the page's language. @default "out of 5" */
  scaleLabel?: string;
  /** The review count line; `count` arrives raw, so format it with the page's locale. @default `${n} review(s)`, `n` grouped by the locale */
  countLabel?: (count: number) => string;
  /** A distribution row's name. @default `${stars} star` */
  starLabel?: (stars: number) => string;
  /** The section's accessible name. @default "Rating summary" */
  "aria-label"?: string;
}

const starLevels = [5, 4, 3, 2, 1];

export function RatingSummary({
  average,
  count,
  distribution,
  scaleLabel = "out of 5",
  countLabel,
  starLabel = (stars) => `${stars} star`,
  "aria-label": ariaLabel = "Rating summary",
}: RatingSummaryProps) {
  // The locale React Aria resolves from the nearest I18nProvider (or the browser), as KeypadEntry
  // reads it: counts are grouped for the reader (2,410), never printed raw.
  const { locale } = useLocale();
  const formatCount = new Intl.NumberFormat(locale).format;
  const countText = countLabel
    ? countLabel(count)
    : `${formatCount(count)} ${count === 1 ? "review" : "reviews"}`;
  return (
    // A section, so its accessible name has a role to belong to: `aria-label` on a bare div is
    // prohibited (axe `aria-prohibited-attr`), and a labelled section is a region landmark.
    <Stack
      as="section"
      direction={{ small: "column", medium: "row" }}
      gap="large"
      className="sd-ratingsummary"
      aria-label={ariaLabel}
    >
      <Stack align="center" gap="2x-small" className="sd-ratingsummary__average">
        <span className="sd-ratingsummary__value sd-type-display-medium">
          {average.toFixed(1)}
        </span>
        {/* The stars restate the number beside them, so they are decoration: the score is read once,
            from the text. */}
        <Rating isReadOnly aria-hidden value={average} />
        <span className="sd-ratingsummary__scale sd-type-caption-medium">{scaleLabel}</span>
        <span className="sd-ratingsummary__count sd-type-caption-medium">
          {countText}
        </span>
      </Stack>
      {/* One grid, every row a subgrid of it: the label and count columns size to their widest
          cell, so all five meters start and end on the same lines whatever the digits. */}
      <div className="sd-ratingsummary__distribution">
        {starLevels.map((stars) => {
          const starCount = distribution.find((item) => item.stars === stars)?.count ?? 0;
          const percentage = count > 0 ? (starCount / count) * 100 : 0;

          return (
            <div key={stars} className="sd-ratingsummary__row">
              <span className="sd-ratingsummary__label sd-type-label-medium">{starLabel(stars)}</span>
              <Meter
                value={percentage}
                aria-label={starLabel(stars)}
                className="sd-ratingsummary__meter"
              />
              <span className="sd-ratingsummary__row-count sd-type-body-medium">
                {formatCount(starCount)}
              </span>
            </div>
          );
        })}
      </div>
    </Stack>
  );
}

/* RatingSummary.css — .sd-ratingsummary (Block)
   Arrangement only: gives the aggregate and distribution flexible responsive columns. The
   distribution is one grid and each row a subgrid of it, so the label and count columns are shared
   and every meter track starts and ends on the same lines. */
.sd-ratingsummary {
  width: 100%;
}

.sd-ratingsummary__average {
  flex: 0 0 auto;
}

.sd-ratingsummary__value,
.sd-ratingsummary__scale,
.sd-ratingsummary__count {
  margin: 0;
}

.sd-ratingsummary__distribution {
  flex: 1 1 auto;
  min-width: 0;
  display: grid;
  grid-template-columns: max-content minmax(0, 1fr) max-content;
  column-gap: var(--sd-space-small);
  row-gap: var(--sd-space-2x-small);
}

.sd-ratingsummary__row {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: subgrid;
  align-items: center;
}

.sd-ratingsummary__row-count {
  font-variant-numeric: tabular-nums;
  text-align: end;
}
